## Code Example
```c
typedef struct waiter { struct waiter *next; task_t *t; } waiter_t;

typedef struct wq { spinlock_t lock; waiter_t *head; bool *flag; } wq_t;

void wait_on(wq_t *q, bool *flag){
  acquire(&q->lock);
  while (!*flag){
    enqueue(q, current); // add to wait list
    release(&q->lock);
    schedule();
    acquire(&q->lock);
  }
  release(&q->lock);
}

void wake_up(wq_t *q){
  acquire(&q->lock);
  *q->flag = true;
  wake_all(q); // wake all waiters
  release(&q->lock);
}
``` 

